sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  c.cancel = function(sys_id) {
    var ga = new GlideAjax('EventActionHandler');
    ga.addParam('sysparm_name', 'cancelEvent');
    ga.addParam('sysparm_event_id', sys_id);
    ga.getXMLAnswer(function(response) {
      alert(response);
      location.reload();
    });
  };

  c.promptReschedule = function(event) {
    var newDate = prompt("Enter new date (yyyy-mm-dd):", event.date.split(" ")[0]);
    if (newDate) {
      var ga = new GlideAjax('EventActionHandler');
      ga.addParam('sysparm_name', 'rescheduleEvent');
      ga.addParam('sysparm_event_id', event.sys_id);
      ga.addParam('sysparm_new_date', newDate);
      ga.getXMLAnswer(function(response) {
        alert(response);
        location.reload();
      });
    }
  };
};

sp_widget.script:
(function() {
  var events = [];
  var now = new GlideDateTime(); // Get current date-time

  var gr = new GlideRecord('x_1790233_event_ma_event_record');
  gr.addQuery('event_date', '>=', now);  // Use GlideDateTime object directly
  gr.orderBy('event_date');
  gr.query();

  while (gr.next()) {
    events.push({
      sys_id: gr.getUniqueValue(),
      name: gr.getValue('event_name'),
      date: gr.getDisplayValue('event_date'),
      location: gr.getValue('location'),
      status: gr.getValue('status')
    });
  }

  data.events = events;
})();
